-- Classes agrupadas condensadas em UMA classe: "Classes Agrupadas".
-- As classes agrupadas por faixa de idade (Amigo - Agrupadas ... Guia de Exploração - Agrupadas) ficam como estão no
-- banco, só ocultas (ativo = false), para o caso de voltarem a ser usadas. O progresso já marcado nelas não é apagado.
-- A nova classe reúne os requisitos de Classes_Agrupadas_Requisitos.md: 134 requisitos e 227 subitens,
-- cada um com a própria caixa de marcar. Pode ser rodada de novo sem perder o que os membros já marcaram.

UPDATE public.classes_requisitos_catalogo
SET ativo = FALSE, updated_at = now()
WHERE ativo = TRUE
  AND classe_nome <> 'Classes Agrupadas'
  AND (classe_nome LIKE '% - Agrupadas' OR classe_nome ILIKE 'Classes agrupadas%');

